components.css:
@font-face{font-family:"Archivo Black";src:url("/assets/fonts/archivo-black.ttf") format("truetype");font-style:normal;font-weight:400;font-display:swap}
.ds-placement-banner{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.6}.ds-placement-banner button{font-family:inherit}

.ds-placement-banner{--celebration-ink:#632731;--celebration-red:#ad2d41;position:relative;isolation:isolate;overflow:hidden;margin:24px 0 12px;background:#ffdf6c;color:var(--celebration-ink);border:0;border-radius:16px}
.ds-placement-content{position:relative;display:grid;place-items:center;min-height:640px;padding:130px 24px 52px}
.ds-placement-copy{position:relative;z-index:2;min-width:0;text-align:center;max-width:660px}
.ds-placement-banner h1{font-family:"Archivo Black",sans-serif;font-weight:400;font-size:clamp(48px,6.2vw,88px);line-height:1.08;letter-spacing:-.035em;margin:0 0 30px;text-wrap:balance}
.ds-placement-banner h1 span{display:block;white-space:nowrap}
.ds-placement-banner h1 span:last-child{color:var(--celebration-red)}
.ds-placement-destination{display:flex;flex-direction:column;gap:8px;margin:0 0 20px}
.ds-placement-destination>span{font-size:15px;line-height:1.5}
.ds-placement-destination>strong{font-size:clamp(28px,3vw,38px);line-height:1.2;letter-spacing:-.025em;font-weight:750;text-decoration:underline;text-decoration-color:#fff8e5;text-decoration-thickness:9px;text-underline-offset:3px;text-decoration-skip-ink:none}
.ds-placement-congrats{font-size:15px;line-height:1.6;margin:0 0 28px}
.ds-celebrate-button{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:50px;padding:13px 22px;background:var(--celebration-red);color:#fff8e5;border:0;border-radius:8px;font-size:14px;font-weight:650;transition:background 120ms ease-out,transform 120ms ease-out;cursor:pointer}
.ds-celebrate-button:hover{background:#862134;transform:translateY(-2px)}
.ds-celebrate-button:active{transform:translateY(0) scale(.97)}
.ds-placement-banner :focus-visible{outline:3px solid #2852a8;outline-offset:5px}
.ds-party-decoration{position:absolute;inset:0;pointer-events:none}
.ds-party-flags{position:absolute;top:0;left:0;width:100%;height:160px}
.ds-party-balloons{position:absolute;width:clamp(135px,18vw,220px);top:175px;overflow:visible}
.ds-balloons-left{left:18px;transform:rotate(-8deg)}
.ds-balloons-right{right:18px;transform:rotate(8deg)}
.ds-balloon{transform-origin:center;transform-box:fill-box}
.ds-party-sprinkles{position:absolute;inset:0;width:100%;height:100%}
.ds-placement-footer{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 28px;background:#fbd25a;font-size:12px;color:var(--celebration-ink)}
.ds-placement-footer a{display:inline-flex;align-items:center;gap:8px;color:inherit;text-decoration:underline;text-underline-offset:4px;min-height:32px}
.ds-placement-footer a:hover{text-decoration-thickness:2px}
.ds-placement-banner ::selection{background:#632731;color:#fff8e5}
#placement-confetti{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:3}
.ds-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
@media(min-width:901px) and (max-width:1200px){.ds-party-balloons{width:145px;top:230px}.ds-balloons-left{left:-34px}.ds-balloons-right{right:-34px}.ds-placement-banner h1{font-size:64px}.ds-placement-content{min-height:650px;padding-inline:74px}}
@media(max-width:700px){.ds-placement-banner{margin-top:18px}.ds-placement-content{min-height:560px;padding:172px 18px 42px;align-items:start}.ds-placement-banner h1{font-size:clamp(38px,10vw,58px);line-height:1.12;margin-bottom:26px}.ds-placement-destination{gap:8px;margin-bottom:18px}.ds-placement-destination>span{font-size:13px}.ds-placement-destination>strong{font-size:27px;text-decoration-thickness:7px}.ds-placement-congrats{font-size:13px;margin-bottom:24px}.ds-party-flags{height:110px;width:190%;left:-45%}.ds-party-balloons{width:80px;top:52px}.ds-balloons-left{left:5px;transform:rotate(-14deg)}.ds-balloons-right{right:5px;transform:rotate(14deg)}.ds-party-sprinkles{opacity:.8}.ds-placement-copy{width:100%}.ds-placement-footer{padding:15px 20px;align-items:center;text-align:center;gap:5px;flex-direction:column}.ds-placement-footer>a{min-height:40px}.ds-celebrate-button{min-height:50px}}
@media(max-width:380px){.ds-placement-banner h1{font-size:35px}.ds-placement-content{padding-inline:14px;min-height:550px}.ds-placement-destination>strong{font-size:24px}.ds-placement-congrats{max-width:25ch;margin-inline:auto}.ds-party-balloons{width:70px}}
@media(prefers-reduced-motion:reduce){.ds-celebrate-button{transition:none}.ds-celebrate-button:hover,.ds-celebrate-button:active{transform:none}}
